### Your Infrastructure in Version Control

ClickOps (clicking through the AWS console) doesn't scale and can't be reproduced. Infrastructure as Code (IaC) means your cloud resources are defined in code files that you commit, review, and automate just like application code.

#### Terraform

Terraform is the industry-standard IaC tool. It works with AWS, GCP, Azure, and hundreds of other providers.

```hcl
# main.tf — define an S3 bucket
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "uploads" {
  bucket = "myapp-user-uploads-prod"
}

resource "aws_s3_bucket_public_access_block" "uploads" {
  bucket = aws_s3_bucket.uploads.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# An RDS PostgreSQL instance
resource "aws_db_instance" "main" {
  identifier        = "myapp-prod"
  engine            = "postgres"
  engine_version    = "16"
  instance_class    = "db.t3.micro"
  allocated_storage = 20
  storage_encrypted = true

  db_name  = "myapp"
  username = "myapp"
  password = var.db_password  # from variables, never hardcoded

  backup_retention_period = 7
  skip_final_snapshot     = false
}
```

```bash
# Plan: preview what Terraform will create/change/destroy
terraform plan

# Apply: actually create the resources
terraform apply

# Destroy: tear down everything
terraform destroy
```

Terraform maintains a **state file** that tracks the current real state of your infrastructure. Store it remotely (e.g., in S3) so teams can share it.

#### AWS CDK (Cloud Development Kit)

If you prefer writing real code over HCL, CDK lets you define infrastructure in TypeScript:

```ts
import * as cdk from 'aws-cdk-lib';
import * as s3 from 'aws-cdk-lib/aws-s3';
import * as rds from 'aws-cdk-lib/aws-rds';

export class MyStack extends cdk.Stack {
  constructor(scope: cdk.App, id: string, props?: cdk.StackProps) {
    super(scope, id, props);

    const bucket = new s3.Bucket(this, 'Uploads', {
      blockPublicAccess: s3.BlockPublicAccess.BLOCK_ALL,
      encryption: s3.BucketEncryption.S3_MANAGED,
      removalPolicy: cdk.RemovalPolicy.RETAIN,
    });

    const database = new rds.DatabaseInstance(this, 'Database', {
      engine: rds.DatabaseInstanceEngine.postgres({ version: rds.PostgresEngineVersion.VER_16 }),
      instanceType: ec2.InstanceType.of(ec2.InstanceClass.T3, ec2.InstanceSize.MICRO),
      storageEncrypted: true,
      backupRetention: cdk.Duration.days(7),
    });
  }
}
```

#### Why IaC Matters

- **Reproducibility**: Spin up identical staging and production environments
- **Code review**: Infra changes go through PRs just like app changes
- **Disaster recovery**: Recreate your entire infrastructure from scratch in minutes
- **Cost tracking**: Know exactly what resources you have

